class HorizontalListNav{constructor(t){this.list=t,this.section=t.parentElement,!(!this.list||!this.section)&&this.init()}init(){this.createButtons(),this.updateButtons(),this.initScrollTracking(),this.initResizeTracking()}createButtons(){this.prevButton=document.createElement("button"),this.prevButton.className="nav--prev",this.prevButton.type="button",this.prevButton.setAttribute("aria-label","\u041F\u0440\u043E\u043A\u0440\u0443\u0442\u0438\u0442\u044C \u043D\u0430\u0437\u0430\u0434"),this.nextButton=document.createElement("button"),this.nextButton.className="nav--next",this.nextButton.type="button",this.nextButton.setAttribute("aria-label","\u041F\u0440\u043E\u043A\u0440\u0443\u0442\u0438\u0442\u044C \u0432\u043F\u0435\u0440\u0451\u0434"),this.section.appendChild(this.prevButton),this.section.appendChild(this.nextButton),this.prevButton.addEventListener("click",()=>this.scrollPrev()),this.nextButton.addEventListener("click",()=>this.scrollNext())}updateButtons(){const t=this.list.scrollLeft,e=this.list.scrollWidth-this.list.clientWidth;if(e<=0){this.prevButton.style.display="none",this.nextButton.style.display="none";return}this.prevButton.style.display=t>5?"":"none",this.nextButton.style.display=t<e-5?"":"none"}scrollPrev(){isPinchZoomed()||this.list.scrollBy({left:-this.list.clientWidth*.8,behavior:"smooth"})}scrollNext(){isPinchZoomed()||this.list.scrollBy({left:this.list.clientWidth*.8,behavior:"smooth"})}initScrollTracking(){this.list.addEventListener("scroll",()=>this.updateButtons(),{passive:!0})}initResizeTracking(){ResizeDispatcher.onResizeDebounced(()=>this.updateButtons())}}function initHorizontalListNav(){[".scrollable-line--list",".reviews--images ul",".reviews--list",".comparison--grid"].forEach(t=>{document.querySelectorAll(t).forEach(e=>{new HorizontalListNav(e)})})}document.readyState==="loading"?document.addEventListener("DOMContentLoaded",initHorizontalListNav):initHorizontalListNav();
